/* Recorded glass + water, CC0. Local inline bank also works on file://. */
(()=>{'use strict';
const encoded={"glass":"","water":"","thin":""};
Object.assign(encoded,window.GlassRewardSoundData||{});
let context,master,compressor,loading,ready=false,error='',played=0,sequence=0,eventGain=1,rattlePackets=0;const buffers={},voices=new Set(),counts={};let lastPayout=-Infinity;
const machine=()=>document.getElementById('pachiDebugMachine');
function enabled(){try{return localStorage.getItem('glassGirlGameSoundV1')!=='off';}catch{return true;}}
function blocked(){return !enabled()||document.hidden||!!machine()?.classList.contains('glass-transition-active')||!!window.GlassModeTransition?.snapshot().active;}
function load(){if(loading)return loading;try{context||=new(window.AudioContext||window.webkitAudioContext)();compressor=context.createDynamicsCompressor();compressor.threshold.value=-9;compressor.knee.value=8;compressor.ratio.value=3;compressor.attack.value=.003;compressor.release.value=.12;master=context.createGain();master.gain.value=window.GlassVolume?.sfx??1;compressor.connect(master).connect(context.destination);loading=Promise.all(Object.entries(encoded).map(async([k,v])=>{buffers[k]=await context.decodeAudioData(Uint8Array.from(atob(v),x=>x.charCodeAt(0)).buffer);})).then(()=>{ready=true;}).catch(e=>{error=e.message;});}catch(e){error=e.message;loading=Promise.resolve();}return loading;}
function stop(){for(const source of voices)try{source.stop();}catch{}voices.clear();}
function sample(key,when,volume,rate,length,cutoff=4200,offset=0){
 volume*=eventGain;
 const source=context.createBufferSource(),gain=context.createGain(),filter=context.createBiquadFilter();
 source.buffer=buffers[key];source.playbackRate.value=rate;filter.type='lowpass';filter.frequency.value=cutoff;filter.Q.value=.35;
 const t=context.currentTime+when,d=Math.min(length,(source.buffer.duration-offset)/rate);
 if(d<=0)return;gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(volume,t+.004);
 if(['crystalBreak','trayReal'].includes(key)){gain.gain.setValueAtTime(volume,t+Math.max(.006,d-.12));gain.gain.linearRampToValueAtTime(0,t+d);}else{gain.gain.setValueAtTime(volume,t+Math.min(.04,d*.3));gain.gain.exponentialRampToValueAtTime(.0001,t+d);}
 source.connect(filter).connect(gain).connect(compressor);voices.add(source);source.onended=()=>{voices.delete(source);source.disconnect();filter.disconnect();gain.disconnect();};source.start(t,offset,d*rate);source.stop(t+d+.01);
}
function trayRattle(type){
 // One uninterrupted real steel-ball recording, no rhythmic tap loop.
 sample('trayReal',.15,type==='premium'?.48:.4,1,type==='premium'?1.3:1.1,5400);
 rattlePackets++;
}
function play(e){
 if(blocked())return false;
 const type=e.type;if(!['start','side','win','premium','payout','reelStop','jackpotConfirm'].includes(type)||type==='reelStop'&&!e.jackpot)return false;
 if(type==='payout'&&performance.now()-lastPayout<180)return false;
 if(!ready){load();return false;}context.resume().catch(()=>{});sequence++;
 eventGain=1;
 if(type==='start'||type==='side'){sample('crystalBreak',0,.14,1,.23,5200);}
 else if(type==='payout'){lastPayout=performance.now();sample('crystalBreak',0,.55,1,.65,6000);trayRattle(type);}
 else if(type==='reelStop'){const c=Math.max(0,Math.min(2,e.column||0));sample('glass',0,.5+c*.1,.72+c*.08,.25,3300);sample('water',.012,.32,.83,.3,2000);sample('thin',.04,.2,.9,.18,4300);}
 else if(type==='jackpotConfirm'){sample('glass',0,.95,.63,.52,3900);sample('water',.008,.75,.72,.65,2600);sample('thin',.035,.52,.88,.38,4800);sample('glass',.105,.3,.82,.34,2500);sample('water',.18,.22,.62,.48,1800);}
 else{const premium=type==='premium';sample('crystalBreak',0,premium?.72:.6,1,premium?.82:.72,6200);trayRattle(type);}
 played++;counts[type]=(counts[type]||0)+1;return true;
}
document.addEventListener('glass-volume-change',()=>{if(master)master.gain.value=window.GlassVolume?.sfx??1;});
function unlock(){if(!enabled())return;load();context?.resume().catch(()=>{});}
document.addEventListener('pointerdown',unlock,{passive:true});document.addEventListener('keydown',unlock);
document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
new MutationObserver(()=>{if(blocked())stop();}).observe(document.documentElement,{subtree:true,attributes:true,attributeFilter:['class']});
document.addEventListener('click',()=>{if(!enabled())stop();});
window.GlassRewardAudio=Object.freeze({handle:play,load,stop,snapshot:()=>({ready,enabled:enabled(),played,active:voices.size,counts:{...counts},rattlePackets,rewardBoost:1,realSteel:true,singleCrystal:true,error,context:context?.state||'none'})});
document.addEventListener('DOMContentLoaded',()=>{const list=document.querySelector('.glass-sfx-list');if(!list)return;for(const [label,event]of [['新・賞球の水晶音',{type:'payout'}],['新・7の停止音',{type:'reelStop',jackpot:true,column:1}],['新・777確定音',{type:'jackpotConfirm'}]]){const button=document.createElement('button');button.type='button';button.textContent=label;button.onclick=()=>{window.GlassGameAudio?.stop();stop();unlock();load().then(()=>play(event));};list.append(button);}});
})();

